package main

import (
	"fmt"
	"unsafe"
)

type Bad struct {
	A bool
	B int64
	C bool
}

type Good struct {
	A bool
	C bool
	B int64
}

func main() {
	// 同样的三个字段，顺序不同：24 字节 vs 16 字节
	fmt.Println("bool,int64,bool =", unsafe.Sizeof(Bad{}))
	fmt.Println("bool,bool,int64 =", unsafe.Sizeof(Good{}))
	fmt.Println("最大对齐 =", unsafe.Alignof(Good{}))
}
